def merge_intervals(intervals):
    if not intervals:
        return []
    copied = [[s, e] for s, e in intervals]
    copied.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = copied[0]
    for s, e in copied[1:]:
        if s <= cur_end:
            if e > cur_end:
                cur_end = e
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

import heapq

def toposort(nodes, edges):
    nodes = list(nodes)
    edges = list(edges)
    indeg = {n: 0 for n in nodes}
    adj = {n: set() for n in nodes}
    seen = set()
    for s, d in edges:
        if s not in adj or d not in adj:
            continue
        if s == d:
            raise ValueError("self loop")
        if (s, d) in seen:
            continue
        seen.add((s, d))
        if d not in adj[s]:
            adj[s].add(d)
            indeg[d] += 1
    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)
    result = []
    indeg_mut = indeg.copy()
    adj_mut = {k: set(v) for k, v in adj.items()}
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in adj_mut[n]:
            indeg_mut[m] -= 1
            if indeg_mut[m] == 0:
                heapq.heappush(heap, m)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    if not items:
        return []
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError
    batches = []
    cur = []
    cur_sum = 0
    for name, w in items:
        if cur_sum + w > limit:
            batches.append(cur)
            cur = [name]
            cur_sum = w
        else:
            cur.append(name)
            cur_sum += w
    batches.append(cur)
    return batches

import re

def parse_env(text):
    env = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f'Invalid line: {raw_line!r}')
        key, val = line.split('=', 1)
        key = key.strip()
        val = val.strip()
        if not key_re.match(key):
            raise ValueError(f'Invalid key: {key!r}')
        if len(val) >= 2 and val[0] == val[-1] and val[0] in ("'", '"'):
            val = val[1:-1]
        env[key] = val
    return env

import codecs

def parse_sse(chunks):
    decoder = codecs.IncrementalDecoder('utf-8')
    buf = ''
    current_parts = []
    events = []

    def dispatch():
        nonlocal current_parts
        if current_parts:
            data = '\n'.join(current_parts)
            if data == '[DONE]':
                return True  # stop
            events.append(data)
        current_parts = []
        return False

    for chunk in chunks:
        buf += decoder.decode(chunk, final=False)
        while True:
            nl = buf.find('\n')
            if nl == -1:
                break
            line = buf[:nl]
            buf = buf[nl + 1:]
            if line.endswith('\r'):
                line = line[:-1]
            if line == '':
                if dispatch():
                    return events
            else:
                if line.startswith('data:'):
                    content = line[5:]
                    if content.startswith(' '):
                        content = content[1:]
                    current_parts.append(content)
                # other fields ignored
    # flush decoder
    buf += decoder.decode(b'', final=True)
    # process any remaining complete lines
    while True:
        nl = buf.find('\n')
        if nl == -1:
            break
        line = buf[:nl]
        buf = buf[nl + 1:]
        if line.endswith('\r'):
            line = line[:-1]
        if line == '':
            if dispatch():
                return events
        else:
            if line.startswith('data:'):
                content = line[5:]
                if content.startswith(' '):
                    content = content[1:]
                current_parts.append(content)
    # unterminated final event is ignored
    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("negative argument")
    if base == 0 or cap == 0:
        return 0.0
    if base >= cap:
        return float(cap)

    # for very large attempt the product will definitely exceed cap
    # use log to avoid a huge loop
    import math
    try:
        max_attempt = math.log2(cap / base) if base > 0 else float('inf')
        if attempt >= max_attempt:
            return float(cap)
    except (ValueError, OverflowError):
        return float(cap)

    # now attempt is small enough to iterate safely
    val = float(base)
    cap_f = float(cap)
    for _ in range(int(attempt)):
        val *= 2.0
        if val >= cap_f:
            return cap_f
    return float(val)
